'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const key='carolina-day-v1', initial={version:1,name:'Rudra',tasks:[],events:[],notes:'',links:[],checkins:{}};
let state=structuredClone(initial), storageOk=true;
try {const saved=JSON.parse(localStorage.getItem(key));if(saved&&validState(saved))state=saved;}catch{storageOk=false}
function validState(s){return s&&s.version===1&&typeof s.name==='string'&&s.name.length<=40&&typeof s.notes==='string'&&Array.isArray(s.tasks)&&Array.isArray(s.events)&&Array.isArray(s.links)&&s.checkins&&typeof s.checkins==='object'&&!Array.isArray(s.checkins)&&s.tasks.length<=10000&&s.events.length<=10000&&[...s.tasks,...s.events].every(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&x.title.length<=180&&typeof x.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&['Personal','Academics','Finance Society'].includes(x.space)&&typeof x.note==='string')&&s.events.every(x=>/^\d{2}:\d{2}$/.test(x.time))&&s.tasks.every(x=>typeof x.done==='boolean'&&['Normal','High','Low'].includes(x.priority))&&s.links.every(x=>x&&typeof x.id==='string'&&typeof x.name==='string'&&safeUrl(x.url))}
function safeUrl(value){try{return ['http:','https:'].includes(new URL(value).protocol)}catch{return false}}
function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function parseDate(s){return new Date(s+'T12:00:00')}
let today=dateKey(new Date()),selected=today,month=parseDate(today),space='All',editing='task',editId=null,mood='',timerRemaining=1500,timerEnd=null,timerInterval=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const color=s=>s==='Finance Society'?'purple':s==='Academics'?'green':'orange';
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageOk=true;return true}catch{storageOk=false;toast('This browser cannot save changes. Export a backup before leaving.');return false}}
let toastTimeout;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),3800)}
function showView(view){$$('.view').forEach(x=>x.classList.toggle('hidden',x.id!==view+'-view'));$$('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#page-name').textContent={today:'My day',calendar:'Calendar',tasks:'All tasks',notes:'Notes & links'}[view];location.hash=view;render();window.scrollTo({top:0,behavior:'smooth'})}
function empty(title,body,icon='✧'){return `<div class="empty"><span class="empty-symbol">${icon}</span><strong>${title}</strong>${body}</div>`}
function render(){const now=new Date();const hour=now.getHours();$('#greeting').innerHTML=`${hour<12?'Good morning':hour<17?'Good afternoon':'Good evening'}, ${esc(state.name)} <span>✦</span>`;$('#header-date').textContent=now.toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});$('.profile>span:nth-child(2)').innerHTML=`${esc(state.name)}’s space<small>Make room for a good day.</small>`;$('.avatar').textContent=state.name.slice(0,1).toUpperCase();$('#schedule-date').textContent=parseDate(selected).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});const dTasks=state.tasks.filter(x=>x.date===today),done=dTasks.filter(x=>x.done).length;$('#event-stat').textContent=state.events.filter(x=>x.date===today).length;$('#done-stat').textContent=`${done} / ${dTasks.length}`;$('#task-count').textContent=state.tasks.filter(x=>!x.done).length;$('#progress-label').textContent=`${done} done`;$('#progress-bar').style.width=(dTasks.length?done/dTasks.length*100:0)+'%';const start=parseDate(selected);start.setDate(start.getDate()-((start.getDay()+6)%7));$('#day-strip').innerHTML=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return `<button data-date="${dateKey(d)}" class="${dateKey(d)===selected?'selected':''}" aria-label="${d.toDateString()}" aria-pressed="${dateKey(d)===selected}"><small>${d.toLocaleDateString(undefined,{weekday:'short'}).toUpperCase()}</small><b>${d.getDate()}</b></button>`}).join('');const events=state.events.filter(x=>x.date===selected).sort((a,b)=>a.time.localeCompare(b.time));const tasks=state.tasks.filter(x=>x.date===selected);$('#agenda').innerHTML=events.map(x=>`<div class="event-row"><span class="event-time">${formatTime(x.time)}</span><button class="event-card ${color(x.space)}" data-edit-event="${esc(x.id)}"><strong>${esc(x.title)}</strong><small>${esc(x.space)}${x.note?' · '+esc(x.note.slice(0,45)):''}</small></button></div>`).join('')+tasks.map(taskRow).join('')||empty('A little breathing room.','Add a plan or a task for this day.','☀');$('#today-tasks').innerHTML=dTasks.sort((a,b)=>Number(a.done)-Number(b.done)).map(taskRow).join('')||empty('Start with one small thing.','What would make today feel good?');renderTasks();renderMonth();renderLinks();const intention=state.checkins[today]?.intention;if(intention){$('.hero h2').textContent=intention;$('.hero .tag').textContent='YOUR INTENTION FOR TODAY'}else{$('.hero h2').innerHTML='You don’t have to do it all.<br>Just the next right thing.';$('.hero .tag').textContent='YOUR DAY, INTENTIONALLY'}}
function formatTime(t){const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`}
function taskRow(t){return `<div class="task-row ${t.done?'done':''}"><button class="task-check" data-toggle="${esc(t.id)}" aria-label="${t.done?'Reopen':'Complete'} ${esc(t.title)}" aria-pressed="${t.done}">${t.done?'✓':''}</button><button class="task-body" data-edit-task="${esc(t.id)}"><strong>${esc(t.title)}</strong><small><i class="dot ${color(t.space)}"></i> ${esc(t.space)} · ${esc(t.date===today?'Today':t.date)}${t.date<today&&!t.done?' · Overdue':''}</small></button>${t.priority==='High'&&!t.done?'<span class="priority">High</span>':''}</div>`}
function renderTasks(){const query=$('#task-search').value.toLowerCase(),filter=$('#task-filter').value;const items=state.tasks.filter(x=>(space==='All'||x.space===space)&&(filter==='all'||(filter==='done'?x.done:!x.done))&&x.title.toLowerCase().includes(query)).sort((a,b)=>a.date.localeCompare(b.date));$('#space-label').textContent=space==='All'?'All spaces':space;$('#all-tasks').innerHTML=items.map(taskRow).join('')||empty('A clear little space.','Add a task, or try another filter.','✓')}
function renderMonth(){const first=new Date(month.getFullYear(),month.getMonth(),1,12);const start=new Date(first);start.setDate(1-((first.getDay()+6)%7));$('#month-title').textContent=first.toLocaleDateString(undefined,{month:'long',year:'numeric'});$('#month-grid').innerHTML=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('')+Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const key=dateKey(d),events=state.events.filter(x=>x.date===key),tasks=state.tasks.filter(x=>x.date===key);return `<div class="month-day ${d.getMonth()!==month.getMonth()?'outside':''} ${key===today?'today':''}" role="button" tabindex="0" data-month-date="${key}" aria-label="${d.toDateString()}, ${events.length} plans, ${tasks.length} tasks"><b>${d.getDate()}</b>${events.slice(0,2).map(x=>`<div class="month-chip">${esc(x.title)}</div>`).join('')}${tasks.slice(0,2).map(x=>`<div class="month-chip task-chip">${x.done?'✓':'○'} ${esc(x.title)}</div>`).join('')}${events.length+tasks.length>Math.min(events.length,2)+Math.min(tasks.length,2)?`<small>+${events.length+tasks.length-Math.min(events.length,2)-Math.min(tasks.length,2)} more</small>`:''}</div>`}).join('')}
function renderLinks(){$('#saved-links').innerHTML=state.links.map(x=>`<div class="saved-link"><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.name)} ↗</a><button data-delete-link="${esc(x.id)}" aria-label="Remove ${esc(x.name)}">×</button></div>`).join('')}
function openEditor(kind,id=null){editing=kind;editId=id;const item=(kind==='task'?state.tasks:state.events).find(x=>x.id===id);$('#editor-title').textContent=(id?'Edit your ':'A new ')+(kind==='task'?'task':'plan');$('#item-title').value=item?.title||'';$('#item-date').value=item?.date||selected;$('#item-time').value=item?.time||'09:00';$('#item-space').value=item?.space||(space==='All'?'Personal':space);$('#item-note').value=item?.note||'';$('#item-priority').value=item?.priority||'Normal';$('#time-field').classList.toggle('hidden',kind==='task');$('#priority-field').classList.toggle('hidden',kind!=='task');$('#delete-item').classList.toggle('hidden',!id);$('#save-item').textContent='Save '+(kind==='task'?'task':'plan');$('#editor').showModal()}
function celebrate(x,y){if(!matchMedia('(prefers-reduced-motion: reduce)').matches){for(let i=0;i<34;i++){const p=document.createElement('i');p.className='confetti-piece';p.style.cssText=`left:${x}px;top:${y}px;background:${['#4b9cd3','#a7cce4','#e0c792','#9cc3b0','#a99bc8'][i%5]};--dx:${(Math.random()-.5)*340}px;--dy:${Math.random()*220-140}px;animation-delay:${Math.random()*.12}s`;$('#confetti').append(p);setTimeout(()=>p.remove(),1600)}}toast(['One small win. Look at you go!','That’s progress. Take it in.','Done! A little lighter, a little closer.'][Math.floor(Math.random()*3)])}
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-month-date]');if(!el)return;if(el.dataset.view)showView(el.dataset.view);if(el.dataset.space){space=el.dataset.space;showView('tasks')}if(el.dataset.date){selected=el.dataset.date;render()}if(el.dataset.monthDate){selected=el.dataset.monthDate;showView('today')}if(el.dataset.toggle){const task=state.tasks.find(x=>x.id===el.dataset.toggle);if(!task)return;task.done=!task.done;const r=el.getBoundingClientRect();save();render();if(task.done)celebrate(r.x+r.width/2,r.y+r.height/2)}if(el.dataset.editTask)openEditor('task',el.dataset.editTask);if(el.dataset.editEvent)openEditor('event',el.dataset.editEvent);if(el.classList.contains('add-task'))openEditor('task');if(el.classList.contains('close-dialog'))el.closest('dialog').close();if(el.dataset.mood){mood=el.dataset.mood;$$('[data-mood]').forEach(x=>x.classList.toggle('chosen',x.dataset.mood===mood))}if(el.dataset.deleteLink){state.links=state.links.filter(x=>x.id!==el.dataset.deleteLink);save();renderLinks()}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.monthDate){e.preventDefault();e.target.click()}});
$('#editor-form').addEventListener('submit',e=>{e.preventDefault();const title=$('#item-title').value.trim();if(!title){$('#item-title').focus();return}const list=editing==='task'?state.tasks:state.events,old=list.find(x=>x.id===editId);const item={id:editId||crypto.randomUUID(),title,date:$('#item-date').value,space:$('#item-space').value,note:$('#item-note').value.trim(),...(editing==='task'?{priority:$('#item-priority').value,done:old?.done||false}:{time:$('#item-time').value||'09:00'})};if(old)Object.assign(old,item);else list.push(item);const persisted=save();$('#editor').close();render();if(persisted)toast(editing==='task'?'A small step, ready when you are.':'Your plan is saved.')});
$('#delete-item').onclick=()=>{const prop=editing==='task'?'tasks':'events';state[prop]=state[prop].filter(x=>x.id!==editId);save();$('#editor').close();render();toast('Removed from your space.')};$('#new-item').onclick=()=>openEditor('task');$('#add-event').onclick=$('#calendar-add').onclick=()=>openEditor('event');$('#see-calendar').onclick=()=>showView('calendar');$('#plan-day').onclick=()=>{selected=today;showView('today');openEditor('task')};$('#task-search').oninput=renderTasks;$('#task-filter').onchange=renderTasks;
$('#prev-month').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1,12);renderMonth()};$('#next-month').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1,12);renderMonth()};$('#this-month').onclick=()=>{month=parseDate(today);selected=today;renderMonth()};
$('#morning').onclick=()=>{const check=state.checkins[today];$('#intention').value=check?.intention||'';mood=check?.mood||'';$$('[data-mood]').forEach(x=>x.classList.toggle('chosen',x.dataset.mood===mood));$('#checkin').showModal()};$('#save-checkin').onclick=()=>{state.checkins[today]={intention:$('#intention').value.trim(),mood};save();$('#checkin').close();render();toast('You’ve got this. One step at a time.')};
function settings(){$('#user-name').value=state.name;$('#settings-dialog').showModal()}$('#settings').onclick=$('#connect').onclick=$('#mobile-settings').onclick=settings;$('#save-settings').onclick=()=>{state.name=$('#user-name').value.trim()||'Rudra';if(save())toast('Your space feels a little more like you.');render()};$('#notepad').value=state.notes;$('#notepad').oninput=()=>{state.notes=$('#notepad').value;$('#note-status').textContent=save()?'Saved in this browser.':'Not saved. Export a backup before leaving.'};
$('#link-form').onsubmit=e=>{e.preventDefault();const url=$('#link-url').value.trim(),name=$('#link-name').value.trim();if(!name||!safeUrl(url)){toast('Use a name and an https:// or http:// link.');return}state.links.push({id:crypto.randomUUID(),name,url});save();e.target.reset();renderLinks()};
function timerPaint(){$('#timer').textContent=`${String(Math.floor(timerRemaining/60)).padStart(2,'0')}:${String(timerRemaining%60).padStart(2,'0')}`}
function tick(){timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));timerPaint();if(timerRemaining===0){clearInterval(timerInterval);timerInterval=null;timerEnd=null;$('#start-focus').textContent='Start again →';$('#focus-message').textContent='You showed up. Take a well-earned break.';celebrate(innerWidth/2,innerHeight/2)}}
$('#start-focus').onclick=()=>{if(timerEnd){tick();clearInterval(timerInterval);timerInterval=null;timerEnd=null;$('#start-focus').textContent='Resume →';return}if(timerRemaining===0)timerRemaining=1500;timerEnd=Date.now()+timerRemaining*1000;timerInterval=setInterval(tick,250);$('#start-focus').textContent='Pause';$('#focus-message').textContent='One thing at a time. You’re doing enough.'};$('#reset-focus').onclick=()=>{clearInterval(timerInterval);timerInterval=null;timerEnd=null;timerRemaining=1500;timerPaint();$('#start-focus').textContent='Start focus →';$('#focus-message').textContent='A quiet 25 minutes, just for you.'};
$('#export-data').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`carolina-day-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your backup is ready.')};$('#import-data').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error();const data=JSON.parse(await file.text());if(!validState(data))throw Error();if(!confirm('Replace this browser’s plans, tasks, and notes with this backup? Export your current data first if you want to keep it.'))return;state=data;const persisted=save();$('#notepad').value=state.notes;$('#user-name').value=state.name;render();if(persisted)toast('Welcome back. Your space is restored.')}catch{toast('This isn’t a valid Carolina Day backup.')}finally{e.target.value=''}};
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['today','calendar','tasks','notes'].includes(view)&&$('#'+view+'-view').classList.contains('hidden'))showView(view)});
setInterval(()=>{const current=dateKey(new Date());if(current!==today){if(selected===today)selected=current;today=current;render()}},30000);
showView(['today','calendar','tasks','notes'].includes(location.hash.slice(1))?location.hash.slice(1):'today');if(!storageOk)toast('Browser storage is unavailable. Export a backup before leaving.');
